        h = N/HORA;
        resto_m = N%HORA;
        m = resto_m/MIN;
        s = resto_m%MIN;
    }
    if (N<3600 && N>=60){ 
        h = 0;
        m = N/MIN;
        s = N%MIN;   
    }
    if (N < 60){
        h = m = 0;
        s = N;
    }
