        if (m <= 9){
            if (s <= 9){
                printf("0%d:0%d:0%d", h, m, s);}
            else
                printf("0%d:0%d:%d", h, m, s);
        }
        else {
            if (s <= 9){
                printf("0%d:%d:0%d", h, m, s);}
            else
                printf("0%d:%d:%d", h, m, s);
        }    
    }
    else {
        if (m <= 9){
            if (s <= 9){
                printf("%d:0%d:0%d", h, m, s);}
            else
                printf("%d:0%d:%d", h, m, s);
        }
        else {
            if (s <= 9){
                printf("%d:%d:0%d", h, m, s);}
            else
                printf("%d:%d:%d", h, m, s);
        }
    }
    return 0;
}

